"""EMAG2v3 surface viewer; native grid in 2D and 2x2 averages in 3D."""
from pathlib import Path
import json
import numpy as np
import pandas as pd
from scipy.interpolate import RegularGridInterpolator
from scipy.ndimage import median_filter,gaussian_filter
from plotly.offline import get_plotlyjs
ROOT=Path(__file__).resolve().parent

def build_viewer():
 data=ROOT/'data';out=ROOT/'output'
 e=np.load(data/'emag2v3/regional_2arcmin.npz');lon=e['lon'];lat=e['lat'];an=e['anomaly']
 lo=lon.reshape(-1,2).mean(1);la=lat.reshape(-1,2).mean(1)
 small=an.reshape(450,2,450,2).mean(axis=(1,3))
 b=pd.read_csv(data/'regional_bathymetry_10N40N_60W20W.csv');g=b.pivot(index='lat',columns='lon',values='depth_m').sort_index().sort_index(axis=1)
 raw=g.to_numpy();med=median_filter(raw,3,mode='nearest');smooth=gaussian_filter(np.where(abs(raw-med)>800,med,raw),.85,mode='nearest')
 terrain=RegularGridInterpolator((g.index.to_numpy(),g.columns.to_numpy()),smooth)
 xx,yy=np.meshgrid(lo,la);points=np.column_stack([yy.ravel(),xx.ravel()]);depth=terrain(points).reshape(450,450)
 age=pd.read_csv(data/'seafloor_age_earthbyte_10N40N_55W25W.csv').pivot(index='lat',columns='lon',values='seafloor_age_Ma').sort_index().sort_index(axis=1)
 ages=RegularGridInterpolator((age.index.to_numpy(),age.columns.to_numpy()),age.to_numpy())(points).reshape(450,450)
 def arr(x,n=2):
  a=np.round(x,n).astype(object);a[~np.isfinite(np.asarray(x))]=None;return a.tolist()
 point_stride=4
 point_x,point_y=np.meshgrid(g.columns.to_numpy()[::point_stride],g.index.to_numpy()[::point_stride])
 ridge=pd.read_csv(out/'regional_ridge_axis.csv')
 payload=dict(lon=arr(lon,6),lat=arr(lat,6),anomaly=arr(an),x=arr(lo,6),y=arr(la,6),a=arr(small),depth=arr(depth,1),age=arr(ages),etopo_x=arr(point_x.ravel(),6),etopo_y=arr(point_y.ravel(),6),etopo_z=arr((raw[::point_stride,::point_stride]+35).ravel(),1),etopo_depth=arr(raw[::point_stride,::point_stride].ravel(),1),ridge_x=arr(ridge.lon.to_numpy(),3),ridge_y=arr(ridge.lat.to_numpy(),3),ridge_z=arr(ridge.depth_m.to_numpy()+120,1),ridge_depth=arr(ridge.depth_m.to_numpy(),1))
 template=r'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>북대서양 자기 이상과 해저 지형</title><style>
:root{--ink:#10233a;--muted:#617289;--line:#dce5ee;--panel:#fff;--navy:#0a2036;--blue:#1769aa;--soft:#f3f7fa;--accent:#42b5c8}*{box-sizing:border-box}html{background:#edf3f7}body{margin:0;color:var(--ink);font:14px/1.55 Pretendard,"Noto Sans KR","Malgun Gothic",sans-serif;background:radial-gradient(circle at 90% -10%,#d9eef2 0,transparent 32%),#edf3f7}main{max-width:1460px;margin:auto;padding:18px}.hero{position:relative;overflow:hidden;display:flex;justify-content:space-between;gap:28px;align-items:end;padding:25px 30px 23px;border-radius:18px 18px 0 0;color:#fff;background:linear-gradient(118deg,#071b2d 0%,#0d3551 60%,#12647a 100%)}.hero:after{content:"";position:absolute;right:-70px;top:-100px;width:360px;height:260px;border:1px solid rgba(255,255,255,.12);border-radius:50%;transform:rotate(-16deg);box-shadow:0 0 0 38px rgba(255,255,255,.035),0 0 0 76px rgba(255,255,255,.025)}.eyebrow{margin-bottom:7px;color:#79d6e2;font-size:11px;font-weight:800;letter-spacing:.16em;text-transform:uppercase}.hero h1{margin:0;font-size:clamp(24px,3vw,37px);line-height:1.18;letter-spacing:-.045em}.hero p{max-width:760px;margin:8px 0 0;color:#c9dbe7}.facts{z-index:1;display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.fact{min-width:102px;padding:9px 12px;border:1px solid rgba(255,255,255,.15);border-radius:10px;background:rgba(4,20,34,.35);backdrop-filter:blur(8px)}.fact b{display:block;font-size:15px}.fact span{color:#abc4d4;font-size:11px}.workspace{overflow:hidden;border-radius:0 0 18px 18px;background:var(--panel);box-shadow:0 18px 45px rgba(20,46,70,.12)}.toolbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:12px 16px;border-bottom:1px solid var(--line);background:#fbfdfe}.group{display:flex;align-items:center;gap:5px;padding:4px;border-radius:10px;background:#edf3f7}.spacer{flex:1}.toolbar button,.toolbar select{height:34px;border:1px solid transparent;border-radius:7px;padding:0 12px;color:#385069;background:transparent;font:700 12px inherit;cursor:pointer;transition:.16s ease}.toolbar button:hover,.toolbar select:hover{border-color:#c9d7e3;background:#fff}.toolbar button[aria-pressed="true"]{color:#fff;background:var(--navy);box-shadow:0 2px 8px rgba(7,27,45,.2)}.toolbar button:disabled{cursor:not-allowed;opacity:.4}.toolbar label{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:12px}.toolbar select{outline:none;border-color:#d4e0e9;background:#fff;font-weight:700}.statusbar{display:flex;align-items:center;gap:8px;padding:8px 18px;color:#617289;background:#f8fafc;font-size:12px}.statusbar:before{content:"";width:7px;height:7px;border-radius:50%;background:#2fb391;box-shadow:0 0 0 3px #d8f1e9}.plot-wrap{position:relative;padding:0 8px 8px;background:#fff}#map3d,#map2d{height:690px;border-radius:12px;background:#fff}#map2d{display:none}.notes{display:grid;grid-template-columns:1.15fr 1fr 1fr;gap:10px;padding:0 16px 16px}.note{padding:14px 15px;border:1px solid var(--line);border-radius:11px;background:#f8fafc}.note-kicker{display:block;margin-bottom:4px;color:#176f89;font-size:10px;font-weight:800;letter-spacing:.1em}.note b{font-size:13px}.note p{margin:4px 0 0;color:var(--muted);font-size:12px}.sources{padding:0 18px 17px;color:#75869a;font-size:11px}.sources a{color:#416d8d;text-decoration:none}.sources a:hover{text-decoration:underline}@media(max-width:760px){main{padding:0}.hero{align-items:start;flex-direction:column;border-radius:0;padding:22px 18px}.facts{justify-content:start}.workspace{border-radius:0}.toolbar{padding:10px}.spacer{display:none}.notes{grid-template-columns:1fr}.fact{min-width:90px}#map3d,#map2d{height:590px}}
</style></head><body><main><header class="hero"><div><div class="eyebrow">Earth Science Data Explorer</div><h1>북대서양 자기 이상과 해저 지형</h1><p>해저 지형 위에 NOAA EMAG2v3 자기 이상을 겹쳐 중앙해령 주변의 공간 패턴을 탐색합니다.</p></div><div class="facts"><div class="fact"><b>30° × 30°</b><span>분석 영역</span></div><div class="fact"><b>2 arc-min</b><span>자기 격자</span></div><div class="fact"><b>±500 nT</b><span>표시 범위</span></div></div></header><section class="workspace"><div class="toolbar"><div class="group"><button id="b3" aria-pressed="true">3D 지형</button><button id="b2" aria-pressed="false">평면 지도</button></div><label>표면색 <select id="layer" aria-label="표면색"><option value="a">자기 이상</option><option value="depth">수심</option><option value="age">지각 연령</option></select></label><div class="group views" aria-label="고정 시점"><button id="vx" title="X축 방향에서 보기">X</button><button id="vy" title="Y축 방향에서 보기">Y</button><button id="vz" title="위에서 보기">Z</button></div><span class="spacer"></span><button id="ridge" aria-pressed="true">해령 축 숨김</button><button id="etopo" aria-pressed="true">ETOPO 점 숨김</button><button id="reset">↺ 시점 초기화</button></div><div class="statusbar" id="status">지도를 불러오는 중…</div><div class="plot-wrap"><div id="map3d"></div><div id="map2d"></div></div><div class="notes"><article class="note"><span class="note-kicker">COLOR</span><b>빨강은 양, 파랑은 음의 자기 이상</b><p>색은 정상·역자화를 직접 분류한 값이 아닙니다. 범례와 커서의 nT 값을 기준으로 읽으세요.</p></article><article class="note"><span class="note-kicker">GRID</span><b>EMAG2v3 격자와 ETOPO 표본</b><p>평면 지도는 900 × 900 원격자입니다. 분홍점은 ETOPO 표본, 노란선은 지형으로 추정한 해령 축입니다.</p></article><article class="note"><span class="note-kicker">CAUTION</span><b>3D 수직 축척은 과장됨</b><p>수심은 지형을 읽기 쉽게 보간했습니다. 확대해도 새로운 직접 관측값이 생기지는 않습니다.</p></article></div><footer class="sources">자료 출처 · <a href="https://doi.org/10.7289/V5H70CVX" target="_blank">NOAA EMAG2v3</a> · <a href="https://repository.library.noaa.gov/view/noaa/45599" target="_blank">제작 방법</a> · <a href="https://www.ncei.noaa.gov/products/etopo-global-relief-model" target="_blank">ETOPO 2022</a> · <a href="https://doi.org/10.1029/2020GC009214" target="_blank">EarthByte</a></footer></section></main><script>__PLOTLY__</script><script>const D=__DATA__;
const blueRed=[[0,'#061c74'],[.2,'#064bcc'],[.4,'#1674ef'],[.47,'#66a9fa'],[.5,'#f4f4f4'],[.53,'#ff9589'],[.6,'#f33425'],[.8,'#c70c22'],[1,'#78001c']];
const sets={a:{values:D.a,scale:blueRed,min:-500,max:500,title:'자기 이상 (nT)'},depth:{values:D.depth,scale:'Earth',min:-7000,max:500,title:'고도 / 수심 (m)'},age:{values:D.age,scale:[[0,'#2582fa'],[.4,'#55b9cf'],[.7,'#a8d98a'],[1,'#fde737']],min:0,max:120.6,title:'지각 연령 (Ma)'}};
const cameras={free:{eye:{x:1.05,y:-1.35,z:1.45},up:{x:0,y:0,z:1}},x:{eye:{x:2.45,y:0,z:.05},up:{x:0,y:0,z:1}},y:{eye:{x:0,y:2.45,z:.05},up:{x:0,y:0,z:1}},z:{eye:{x:0,y:0,z:2.65},up:{x:0,y:1,z:0}}};
const camera=cameras.free;
let view='3d',made2=false;
const config={responsive:true,displaylogo:false,scrollZoom:false,modeBarButtonsToRemove:['sendDataToCloud','share']};
const hover3='경도 %{x:.3f}° · 위도 %{y:.3f}°<br>표시용 고도 %{z:.0f} m<br>표면값 %{surfacecolor:.2f}<extra></extra>';
const axisStyle={showbackground:true,backgroundcolor:'#f3f7fa',gridcolor:'#d6e1e9',zerolinecolor:'#a9bac7',tickfont:{color:'#52677c',size:11},title:{font:{color:'#2d455d',size:12}}};
Plotly.newPlot('map3d',[{type:'surface',x:D.x,y:D.y,z:D.depth,surfacecolor:D.a,colorscale:blueRed,cmin:-500,cmax:500,colorbar:{title:{text:'자기 이상 (nT)',font:{size:12}},len:.76,thickness:14,outlinewidth:0,tickfont:{size:10,color:'#52677c'}},lighting:{ambient:.28,diffuse:.96,specular:.16,roughness:.72,fresnel:.08},lightposition:{x:-1400,y:-1900,z:2600},hovertemplate:hover3},{type:'scatter3d',name:'ETOPO 원격자 표본',x:D.etopo_x,y:D.etopo_y,z:D.etopo_z,mode:'markers',marker:{size:1.35,color:'#ff7f8a',opacity:.72,line:{width:0}},customdata:D.etopo_depth,hovertemplate:'ETOPO 원격자 표본<br>경도 %{x:.2f}° · 위도 %{y:.2f}°<br>수심/고도 %{customdata:.0f} m<extra></extra>'},{type:'scatter3d',name:'추정 해령 축',x:D.ridge_x,y:D.ridge_y,z:D.ridge_z,mode:'lines',line:{color:'#ffd43b',width:7},customdata:D.ridge_depth,hovertemplate:'추정 해령 축<br>경도 %{x:.2f}° · 위도 %{y:.2f}°N<br>수심 %{customdata:.0f} m<extra></extra>'}],{paper_bgcolor:'#ffffff',font:{family:'Pretendard, Noto Sans KR, Malgun Gothic, sans-serif',color:'#294159'},margin:{l:0,r:55,t:6,b:0},scene:{xaxis:{...axisStyle,title:{text:'경도 (°)'},range:[-55,-25]},yaxis:{...axisStyle,title:{text:'위도 (°N)'},range:[10,40]},zaxis:{...axisStyle,title:{text:'고도 (m)'},range:[-7000,1200]},aspectmode:'manual',aspectratio:{x:1,y:1.15,z:.3},camera},legend:{orientation:'h',x:.02,y:.02,bgcolor:'rgba(255,255,255,.78)',font:{size:11}}},config).then(updateStatus);
function updateStatus(){document.getElementById('status').textContent=view==='3d'?'3D 보기 · 자기 격자 4분각 · 드래그하여 회전하고 스크롤로 확대':'평면 보기 · 원본 2분각 810,000칸 · 드래그로 확대하고 더블클릭으로 복귀';}
async function show(v){view=v;document.getElementById('map3d').style.display=v==='3d'?'block':'none';document.getElementById('map2d').style.display=v==='2d'?'block':'none';document.getElementById('b3').setAttribute('aria-pressed',v==='3d');document.getElementById('b2').setAttribute('aria-pressed',v==='2d');['layer','etopo','ridge','vx','vy','vz'].forEach(id=>document.getElementById(id).disabled=v==='2d');if(v==='2d'&&!made2){await Plotly.newPlot('map2d',[{type:'heatmap',x:D.lon,y:D.lat,z:D.anomaly,colorscale:blueRed,zmin:-500,zmax:500,zsmooth:false,colorbar:{title:{text:'자기 이상 (nT)',font:{size:12}},len:.82,thickness:14,outlinewidth:0,tickfont:{size:10,color:'#52677c'}},hovertemplate:'%{x:.3f}°, %{y:.3f}°<br>EMAG2v3 %{z:.2f} nT<extra></extra>'}],{paper_bgcolor:'#fff',plot_bgcolor:'#f3f7fa',font:{family:'Pretendard, Noto Sans KR, Malgun Gothic, sans-serif',color:'#294159'},margin:{l:65,r:65,t:12,b:55},xaxis:{title:{text:'경도 (°)'},range:[-55,-25],constrain:'domain',gridcolor:'#dce5ec',zeroline:false},yaxis:{title:{text:'위도 (°N)'},range:[10,40],scaleanchor:'x',scaleratio:1/Math.cos(25*Math.PI/180),gridcolor:'#dce5ec',zeroline:false},dragmode:'zoom'},config);made2=true;}Plotly.Plots.resize(v==='3d'?'map3d':'map2d');updateStatus();}
document.getElementById('b3').onclick=()=>show('3d');document.getElementById('b2').onclick=()=>show('2d');
document.getElementById('layer').onchange=e=>{const s=sets[e.target.value];Plotly.restyle('map3d',{surfacecolor:[s.values],colorscale:[s.scale],cmin:s.min,cmax:s.max,'colorbar.title.text':s.title,hovertemplate:'경도 %{x:.3f}° · 위도 %{y:.3f}°<br>표시용 고도 %{z:.0f} m<br>'+s.title+' %{surfacecolor:.2f}<extra></extra>'},[0]);};
document.getElementById('etopo').onclick=e=>{const show=e.currentTarget.getAttribute('aria-pressed')!=='true';Plotly.restyle('map3d',{visible:show},[1]);e.currentTarget.setAttribute('aria-pressed',show);e.currentTarget.textContent=show?'ETOPO 점 숨김':'ETOPO 점 표시';};
document.getElementById('ridge').onclick=e=>{const show=e.currentTarget.getAttribute('aria-pressed')!=='true';Plotly.restyle('map3d',{visible:show},[2]);e.currentTarget.setAttribute('aria-pressed',show);e.currentTarget.textContent=show?'해령 축 숨김':'해령 축 표시';};
function setCamera(name){Plotly.relayout('map3d',{'scene.camera':cameras[name]});['x','y','z'].forEach(k=>document.getElementById('v'+k).setAttribute('aria-pressed',k===name));}
['x','y','z'].forEach(k=>document.getElementById('v'+k).onclick=()=>setCamera(k));
document.getElementById('reset').onclick=()=>{if(view==='3d'){Plotly.relayout('map3d',{'scene.camera':camera,'scene.xaxis.range':[-55,-25],'scene.yaxis.range':[10,40],'scene.zaxis.range':[-7000,1200]});['x','y','z'].forEach(k=>document.getElementById('v'+k).setAttribute('aria-pressed','false'));}else Plotly.relayout('map2d',{'xaxis.range':[-55,-25],'yaxis.range':[10,40]});};
</script></body></html>'''
 html=template.replace('__PLOTLY__',get_plotlyjs()).replace('__DATA__',json.dumps(payload,separators=(',',':'),allow_nan=False))
 (out/'12_ridge_focused_3d_heightmap.html').write_text(html,encoding='utf-8')
 (data/'emag2v3/viewer_summary.json').write_text(json.dumps(dict(native_shape=list(an.shape),display3d_shape=list(small.shape),native_range=[float(an.min()),float(an.max())],native_valid=int(np.isfinite(an).sum()),color_limit_nT=500,saturated_fraction=float(np.mean(abs(an)>500)),source='EMAG2_V3_20170530_SeaLevel'),indent=2))
 print('EMAG viewer ready',len(html))
 return None
if __name__=='__main__':build_viewer()
